// SPDX-License-Identifier: Apache-2.0
//! Per-kernel fixture validation. A statement-for-statement port of
//! `tests/unit/test_ops.c`.
//!
//! Each fixture under `fixtures/ops/` is generated by `tools/emit_fixtures.py` from the
//! pure-torch reference and carries its own weights, inputs and expected outputs. These
//! tests read them and assert the Rust kernels reproduce the reference, within the
//! manifest's tolerances.
//!
//! Tolerances come from `fixtures/ops/MANIFEST.json` (its `tolerance.fp32_abs` /
//! `fp32_rel` keys), falling back to `1e-4` / `1e-3` only when the manifest is absent. A
//! skipped case is a failure, exactly as the C harness counts a skip as a non-zero exit;
//! no test here skips.

// The kernels under test are a statement-for-statement port of the C source, and this
// harness mirrors `tests/unit/test_ops.c` the same way: the index loops and the wide
// fixture-driven signatures are what keep the two diffable side by side.
#![allow(clippy::needless_range_loop, clippy::too_many_arguments)]

mod support;
use support::{
    arr, arr_u8, assert_abs_max, assert_close, boolean, num_f32, num_i32, shape, Fixtures,
};

use k3::cfg::Cfg;
use k3::ops::{
    attn_res, decoder_layer, kda_decay, kda_layer, kda_step, matmul, matmul_bf16, matmul_mxfp4,
    mla, moe, mxfp4_dequant, rmsnorm, router, shortconv, situ_glu, Attn, KdaW, LayerW, MlaW, MoeW,
    WMat,
};
use k3::ops::{bf16f, l2norm};

// ---------------------------------------------------------------------- helpers ----

/// Pack the routed expert weights from a fixture into one contiguous bank, exactly as
/// C's `pack_experts` does. The MoE kernels index the bank as `w1[expert * inter * latent
/// ..]`, `w3` the same, and `w2[expert * latent * inter ..]`. test_ops.c:612.
fn pack_experts(r: &serde_json::Value, fmt: &str, n: usize, per: usize) -> Vec<f32> {
    let mut w = vec![0.0f32; per * n];
    for e in 0..n {
        let key = fmt.replace("{}", &e.to_string());
        let a = arr(r, &key);
        assert_eq!(a.len(), per, "expert {e} key {key}: {} != {}", a.len(), per);
        w[e * per..(e + 1) * per].copy_from_slice(&a);
    }
    w
}
/// A `Cfg` with every field zeroed, the Rust equivalent of C's `memset(&c, 0, sizeof c)`.
/// `Cfg` does not derive `Default` (it owns a `Vec`), so the tests build it literally.
/// This mirrors `cfg::Cfg::from_value` and `main::real_cfg_hardcoded`, which both construct
/// the struct field by field. scale_test.c:57.
fn cfg_zero() -> Cfg {
    Cfg {
        hidden: 0,
        n_layers: 0,
        vocab: 0,
        rms_eps: 0.0,
        kda_heads: 0,
        kda_head_dim: 0,
        conv_k: 0,
        gate_lb: 0.0,
        n_heads: 0,
        q_lora: 0,
        kv_lora: 0,
        qk_nope: 0,
        qk_rope: 0,
        v_head: 0,
        mla_out_gate: 0,
        n_experts: 0,
        topk: 0,
        n_shared: 0,
        latent: 0,
        moe_inter: 0,
        routed_scale: 0.0,
        moe_renorm: 0,
        latent_norm: 0,
        first_dense: 0,
        dense_inter: 0,
        attn_res_block: 0,
        situ_b1: 0.0,
        situ_b2: 0.0,
        full_attn: Vec::new(),
    }
}

// ---------------------------------------------------------------------- rmsnorm ----

#[test]
fn rmsnorm_case() {
    // t_rmsnorm. test_ops.c:130.
    let f = Fixtures::ops();
    let r = f.load("rmsnorm");
    let w = arr(&r, "weight");
    let x = arr(&r, "in");
    let e = arr(&r, "out");
    let eps = num_f32(&r, "eps", 1e-5);
    let n = w.len();
    let rows = x.len() / n;
    let mut y = vec![0.0f32; x.len()];
    for i in 0..rows {
        rmsnorm(&mut y[i * n..(i + 1) * n], &x[i * n..(i + 1) * n], &w, eps);
    }
    assert_close("rmsnorm", &y, &e, f.atol, f.rtol);
}

// ---------------------------------------------------------------------- situ_glu ----

#[test]
fn situ_glu_case() {
    // t_situ. test_ops.c:148. SiTU-GLU over a `[R, 2*W]` input laid out `[gate | up]`.
    let f = Fixtures::ops();
    let r = f.load("situ_glu");
    let x = arr(&r, "in");
    let e = arr(&r, "out");
    let b1 = num_f32(&r, "beta", 4.0);
    let b2 = num_f32(&r, "linear_beta", 25.0);
    let din = shape(&r, "in");
    let dout = shape(&r, "out");
    assert_eq!(din.len(), 2, "situ_glu: in must be rank 2");
    assert_eq!(dout.len(), 2, "situ_glu: out must be rank 2");
    let rows = dout[0] as usize;
    let w = dout[1] as usize;
    assert_eq!(
        din[0] as usize, rows,
        "situ_glu: in row count {} != out row count {}",
        din[0], rows
    );
    assert_eq!(
        din[1] as usize,
        2 * w,
        "situ_glu: in width {} != 2 * out width {}",
        din[1],
        2 * w
    );
    let mut y = vec![0.0f32; e.len()];
    for i in 0..rows {
        situ_glu(
            &mut y[i * w..(i + 1) * w],
            &x[i * 2 * w..(i + 1) * 2 * w],
            b1,
            b2,
        );
    }
    assert_close("situ_glu", &y, &e, f.atol, f.rtol);

    // The soft cap is the one property SiTU-GLU guarantees: |out| <= b1*b2, for any input
    // whatsoever. Violating it means a tanh was dropped or applied to the wrong operand,
    // so this counts as a failure rather than a warning. test_ops.c:176.
    let mx = y.iter().fold(0.0f32, |a, &v| a.max(v.abs()));
    assert!(
        mx <= b1 * b2 + 1e-2,
        "situ_glu: |out|={mx:.3} exceeds b1*b2={} (a tanh is missing or applied to the wrong operand)",
        b1 * b2
    );
}

// ---------------------------------------------------------------------- shortconv ----

#[test]
fn shortconv_case() {
    // t_shortconv. test_ops.c:190. The fixture's weight is `[channels, 1, k]` which
    // flattens to `[channels][k]`, the layout `shortconv_ip` indexes as `w[c*k + j]`.
    let f = Fixtures::ops();
    let r = f.load("shortconv");
    let w = arr(&r, "weight");
    let x = arr(&r, "in");
    let e = arr(&r, "out");
    let st = arr(&r, "state_after");
    let xn = arr(&r, "in_next");
    let en = arr(&r, "out_next");
    let k = num_i32(&r, "kernel", 4) as usize;
    let c = num_i32(&r, "channels", 0) as usize;
    assert!(c > 0, "shortconv: channels missing");
    let t_len = x.len() / c;
    let mut y = vec![0.0f32; x.len()];
    let mut s = vec![0.0f32; c * (k - 1)];
    shortconv(&mut y, &x, &w, Some(&mut s), c, k, t_len);
    assert_close("shortconv", &y, &e, f.atol, f.rtol);
    assert_close("conv_state", &s, &st, f.atol, f.rtol);

    // CONTINUATION. Feed the state from the first call straight into a second call over
    // in_next, and require out_next. This is the only check in the suite that can see the
    // READ side of the state. test_ops.c:216.
    let t2 = xn.len() / c;
    let mut y2 = vec![0.0f32; xn.len()];
    shortconv(&mut y2, &xn, &w, Some(&mut s), c, k, t2);
    assert_close("conv_continuation", &y2, &en, f.atol, f.rtol);
}

// ---------------------------------------------------------------------- kda_decay ----

#[test]
fn kda_decay_case() {
    // t_decay. test_ops.c:231. Drives the engine's own decay kernel forward from the
    // fixture's z and compares its g/alpha to torch elementwise. The absolute 1e-5 bound
    // is the C test's own, not the manifest tolerance.
    let f = Fixtures::ops();
    let r = f.load("kda_decay");
    let a_log = arr(&r, "A_log");
    let dt_bias = arr(&r, "dt_bias");
    let eg = arr(&r, "g");
    let ea = arr(&r, "alpha");
    let z = arr(&r, "z");
    let lb = num_f32(&r, "lower_bound", -5.0);
    let h = a_log.len();
    let d = dt_bias.len() / h;
    let tok = z.len() / dt_bias.len();
    let mut gc = vec![0.0f32; eg.len()];
    let mut ac = vec![0.0f32; ea.len()];
    let nb = dt_bias.len();
    for t in 0..tok {
        kda_decay(
            &mut gc[t * nb..(t + 1) * nb],
            &mut ac[t * nb..(t + 1) * nb],
            &z[t * nb..(t + 1) * nb],
            &a_log,
            &dt_bias,
            h,
            d,
            lb,
        );
    }
    // A_log spans linspace(-0.4, 1.2) across heads, so a per-channel misindex moves every
    // element and shows up here immediately. test_ops.c:262.
    assert_abs_max("kda_decay_g", &gc, &eg, 1e-5);
    assert_abs_max("kda_decay_alpha", &ac, &ea, 1e-5);
}

// ---------------------------------------------------------------------- kda_recur ----

fn kda_recur_case(file: &str) {
    // t_recur. test_ops.c:307. The isolated recurrence: decay, then the rank-one delta
    // write, then read the ALREADY UPDATED state. Any permutation runs cleanly and
    // produces a wrong model, so it gets its own test at T=1 and T=8.
    let f = Fixtures::ops();
    let r = f.load(file);
    let t = num_i32(&r, "T", 0) as usize;
    let h = num_i32(&r, "H", 0) as usize;
    let dk = num_i32(&r, "d_k", 0) as usize;
    let dv = num_i32(&r, "d_v", dk as i32) as usize;
    let qs = num_f32(&r, "q_scale", 1.0);
    let q = arr(&r, "q");
    let k = arr(&r, "k");
    let v = arr(&r, "v");
    let al = arr(&r, "alpha");
    let bt = arr(&r, "beta");
    let eo = arr(&r, "out");
    let es = arr(&r, "state_out");
    assert!(t > 0 && h > 0 && dk > 0, "{file}: T/H/d_k missing");

    let mut s = vec![0.0f32; h * dk * dv];
    let mut out = vec![0.0f32; t * h * dv];
    let mut qs_ = vec![0.0f32; dk];
    for ti in 0..t {
        for head in 0..h {
            let off = (ti * h + head) * dk;
            for i in 0..dk {
                qs_[i] = q[off + i] * qs; // d_k^-0.5
            }
            kda_step(
                &mut s[head * dk * dv..(head + 1) * dk * dv],
                &mut out[(ti * h + head) * dv..(ti * h + head + 1) * dv],
                &qs_,
                &k[off..off + dk],
                &v[off..off + dk],
                &al[(ti * h + head) * dk..(ti * h + head + 1) * dk],
                bt[ti * h + head],
                dk,
                dv,
            );
        }
    }
    assert_close(&format!("{file}_out"), &out, &eo, f.atol, f.rtol);
    assert_close(&format!("{file}_state"), &s, &es, f.atol, f.rtol);
}

#[test]
fn kda_recur1() {
    kda_recur_case("kda_recur1");
}

#[test]
fn kda_recur8() {
    kda_recur_case("kda_recur8");
}

// ---------------------------------------------------------------------- router ----

#[test]
fn router_case() {
    // t_router. test_ops.c:350. Indices are compared as SETS because the reference uses
    // topk(sorted=False), whose order is unspecified. Weights are matched by expert id.
    let f = Fixtures::ops();
    let r = f.load("router");
    let w = arr(&r, "gate_weight");
    let bias = arr(&r, "bias");
    let x = arr(&r, "in");
    let eidx = arr(&r, "topk_idx");
    let ewt = arr(&r, "topk_weight");
    let k = num_i32(&r, "top_k", 0) as usize;
    let e = num_i32(&r, "n_experts", 0) as usize;
    assert!(k > 0 && e > 0, "router: top_k/n_experts missing");
    let hidden = w.len() / e;
    let rows = x.len() / hidden;
    let mut gi = vec![0i32; k];
    let mut gw = vec![0.0f32; k];
    let mut set_ok = true;
    let mut worst_w = 0.0f64;
    for rw in 0..rows {
        router(
            &mut gi,
            &mut gw,
            &x[rw * hidden..(rw + 1) * hidden],
            &w,
            Some(&bias),
            hidden,
            e,
            k,
            true,
            1.0,
        );
        // compare index SETS
        for a in 0..k {
            let mut found = false;
            for b in 0..k {
                if eidx[rw * k + b] as i32 == gi[a] {
                    found = true;
                    break;
                }
            }
            if !found {
                set_ok = false;
                eprintln!(
                    "        row {rw}: C picked expert {}, reference did not",
                    gi[a]
                );
            }
        }
        // match weights by expert id, since order is unspecified
        for a in 0..k {
            for b in 0..k {
                if eidx[rw * k + b] as i32 != gi[a] {
                    continue;
                }
                let d = (gw[a] as f64 - ewt[rw * k + b] as f64).abs();
                let tol = f.atol + f.rtol * (ewt[rw * k + b] as f64).abs();
                if d / tol > worst_w {
                    worst_w = d / tol;
                }
            }
        }
    }
    assert!(set_ok, "router: index sets do not match reference");
    assert!(
        worst_w <= 1.0,
        "router: worst weight {:.2}x tol exceeds 1.0x",
        worst_w
    );
}

// ---------------------------------------------------------------------- attnres ----

#[test]
fn attnres_case() {
    // t_attnres. test_ops.c:277. The fixture carries a fold_hint (norm.weight *
    // proj.weight already folded) and the raw block_residual + prefix_sum sources.
    let f = Fixtures::ops();
    let r = f.load("attnres");
    let px = arr(&r, "prefix_sum");
    let br = arr(&r, "block_residual");
    let fold = arr(&r, "fold_hint");
    let e = arr(&r, "out");
    let eps = num_f32(&r, "eps", 1e-5);
    let n = fold.len();
    let rows = px.len() / n;
    let nblk = br.len() / (rows * n);
    let nsrc = nblk + 1;
    let mut src = vec![0.0f32; nsrc * n];
    let mut y = vec![0.0f32; rows * n];
    for rw in 0..rows {
        for b in 0..nblk {
            src[b * n..(b + 1) * n]
                .copy_from_slice(&br[(rw * nblk + b) * n..(rw * nblk + b + 1) * n]);
        }
        src[nblk * n..(nblk + 1) * n].copy_from_slice(&px[rw * n..(rw + 1) * n]);
        attn_res(&mut y[rw * n..(rw + 1) * n], &src, &fold, nsrc, n, eps);
    }
    assert_close("attn_res", &y, &e, f.atol, f.rtol);
}

// ---------------------------------------------------------------------- mla ----

#[test]
fn mla_case() {
    // t_mla. test_ops.c:407. Gated MLA with all eight weight tensors. The softmax scale is
    // over the full head width (qk_nope + qk_rope), the single-head k_rope is broadcast,
    // and the gate is applied BEFORE o_proj with no norm.
    let f = Fixtures::ops();
    let r = f.load("mla");
    let mut c = cfg_zero();
    c.qk_nope = num_i32(&r, "qk_nope", 0);
    c.qk_rope = num_i32(&r, "qk_rope", 0);
    c.kv_lora = num_i32(&r, "kv_lora", 0);
    c.q_lora = num_i32(&r, "q_lora", 0);
    c.v_head = num_i32(&r, "v_head", 0);
    c.n_heads = num_i32(&r, "n_heads", 0);
    c.rms_eps = num_f32(&r, "rms_eps", 1e-5);

    let x = arr(&r, "in");
    let eo = arr(&r, "out");
    let q_a = arr(&r, "q_a_proj_weight");
    let q_a_norm = arr(&r, "q_a_layernorm_weight");
    let q_b = arr(&r, "q_b_proj_weight");
    let kv_a = arr(&r, "kv_a_proj_with_mqa_weight");
    let kv_a_norm = arr(&r, "kv_a_layernorm_weight");
    let kv_b = arr(&r, "kv_b_proj_weight");
    let o = arr(&r, "o_proj_weight");
    let g = arr(&r, "g_proj_weight");

    let din = shape(&r, "in");
    let t = din[1] as usize;
    c.hidden = din[2] as i32;

    let w = MlaW {
        q_a: WMat::F32(&q_a),
        q_b: WMat::F32(&q_b),
        kv_a: WMat::F32(&kv_a),
        kv_b: WMat::F32(&kv_b),
        o: WMat::F32(&o),
        g: Some(WMat::F32(&g)),
        q_a_norm: &q_a_norm,
        kv_a_norm: &kv_a_norm,
    };
    let scratch_len = k3::ops::mla_scratch(&c, t);
    let mut scratch = vec![0.0f32; scratch_len];
    let mut y = vec![0.0f32; t * c.hidden as usize];
    mla(&mut y, &x, &w, &c, t, &mut scratch);
    assert_close("mla", &y, &eo, f.atol, f.rtol);
}

// ---------------------------------------------------------------------- moe ----

#[test]
fn moe_case() {
    // t_moe. test_ops.c:465. Stable LatentMoE: route full-width, down-project, experts in
    // latent, aggregate RMSNorm, up-project, then the unweighted shared expert.
    let f = Fixtures::ops();
    let r = f.load("moe");
    let mut c = cfg_zero();
    c.hidden = num_i32(&r, "hidden", 0);
    c.latent = num_i32(&r, "latent", 0);
    c.moe_inter = num_i32(&r, "moe_inter", 0);
    c.n_experts = num_i32(&r, "n_experts", 0);
    c.topk = num_i32(&r, "top_k", 0);
    c.n_shared = num_i32(&r, "n_shared", 0);
    c.routed_scale = num_f32(&r, "routed_scale", 1.0);
    c.moe_renorm = num_i32(&r, "renorm", 1);
    c.latent_norm = num_i32(&r, "latent_norm", 1);
    c.rms_eps = num_f32(&r, "rms_eps", 1e-5);
    c.situ_b1 = num_f32(&r, "situ_b1", 4.0);
    c.situ_b2 = num_f32(&r, "situ_b2", 25.0);

    let x = arr(&r, "in");
    let eo = arr(&r, "out");
    let gate = arr(&r, "gate_weight");
    let bias = arr(&r, "e_score_correction_bias");
    let down = arr(&r, "down_weight");
    let up = arr(&r, "up_weight");
    let norm = arr(&r, "norm_weight");
    let sh1 = arr(&r, "shared_w1_weight");
    let sh3 = arr(&r, "shared_w3_weight");
    let sh2 = arr(&r, "shared_w2_weight");

    // routed experts arrive as experts_N_wK_weight; pack them contiguously.
    let per13 = (c.moe_inter * c.latent) as usize;
    let per2 = (c.latent * c.moe_inter) as usize;
    let w1 = pack_experts(&r, "experts_{}_w1_weight", c.n_experts as usize, per13);
    let w3 = pack_experts(&r, "experts_{}_w3_weight", c.n_experts as usize, per13);
    let w2 = pack_experts(&r, "experts_{}_w2_weight", c.n_experts as usize, per2);

    let din = shape(&r, "in");
    let t = din[1] as usize;
    let topk = c.topk as usize;
    let mut idx = vec![0i32; topk];
    let mut wt = vec![0.0f32; topk];
    let mut sc = vec![0.0f32; k3::ops::moe_scratch(&c)];
    let mut y = vec![0.0f32; t * c.hidden as usize];

    let w = MoeW {
        gate: &gate,
        bias: Some(&bias),
        w1: Some(&w1),
        w3: Some(&w3),
        w2: Some(&w2),
        latent_norm: Some(&norm),
        down: WMat::F32(&down),
        up: WMat::F32(&up),
        sh1: WMat::F32(&sh1),
        sh3: WMat::F32(&sh3),
        sh2: WMat::F32(&sh2),
        layer: 0,
        cache_only: false,
    };
    // Resident fixtures: no expert source. `moe` uses the packed w1/w3/w2 bank.
    moe(&mut y, &x, &w, &c, t, &mut idx, &mut wt, &mut sc, None);
    assert_close("moe", &y, &eo, f.atol, f.rtol);
}

// ---------------------------------------------------------------------- kda_layer ----

fn kda_layer_case(file: &str) {
    // t_kda_layer. test_ops.c:552. The full KDA layer: projections, three depthwise convs
    // with fused SiLU, L2Norm on q/k only, the shared low-rank decay, the per-head beta,
    // the recurrence, the head-wise norm and the gate in THAT order, then the output
    // projection. Run at T=1 (decode) and T=8 (where an ordering bug compounds).
    let f = Fixtures::ops();
    let r = f.load(file);
    let mut c = cfg_zero();
    c.kda_heads = num_i32(&r, "H", 0);
    c.kda_head_dim = num_i32(&r, "d_k", 0);
    c.conv_k = num_i32(&r, "conv_k", 4);
    c.gate_lb = num_f32(&r, "lower_bound", -5.0);
    c.rms_eps = num_f32(&r, "rms_eps", 1e-5);

    let x = arr(&r, "in");
    let eo = arr(&r, "out");
    let es = arr(&r, "state_out");

    let q = arr(&r, "q_proj");
    let k = arr(&r, "k_proj");
    let v = arr(&r, "v_proj");
    let q_conv = arr(&r, "q_conv");
    let k_conv = arr(&r, "k_conv");
    let v_conv = arr(&r, "v_conv");
    let f_a = arr(&r, "f_a");
    let f_b = arr(&r, "f_b");
    let a_log = arr(&r, "A_log");
    let dt_bias = arr(&r, "dt_bias");
    let b = arr(&r, "b_proj");
    let g = arr(&r, "g_proj");
    let o_norm = arr(&r, "o_norm");
    let o = arr(&r, "o_proj");

    let din = shape(&r, "in");
    let t = din[1] as usize;
    c.hidden = din[2] as i32;

    let w = KdaW {
        q: WMat::F32(&q),
        k: WMat::F32(&k),
        v: WMat::F32(&v),
        q_conv: &q_conv,
        k_conv: &k_conv,
        v_conv: &v_conv,
        f_a: WMat::F32(&f_a),
        f_b: WMat::F32(&f_b),
        a_log: &a_log,
        dt_bias: &dt_bias,
        b: WMat::F32(&b),
        g: WMat::F32(&g),
        o_norm: &o_norm,
        o: WMat::F32(&o),
    };
    let p = (c.kda_heads * c.kda_head_dim) as usize;
    let hist = (c.conv_k - 1) as usize;
    let mut st = vec![0.0f32; p * c.kda_head_dim as usize + 3 * p * hist];
    let mut sc = vec![0.0f32; k3::ops::kda_scratch(&c, t)];
    let mut y = vec![0.0f32; t * c.hidden as usize];
    kda_layer(&mut y, &x, &w, &c, t, Some(&mut st), &mut sc);
    assert_close(&format!("{file}_out"), &y, &eo, f.atol, f.rtol);
    // The fixture records only the recurrent matrix (H*D*D); the buffer also carries the
    // ShortConv history behind it. C's report() compares the fixture's length, so slice.
    assert_close(
        &format!("{file}_state"),
        &st[..es.len()],
        &es,
        f.atol,
        f.rtol,
    );
}

