// ---------------------------------------------------------------------- layer ----

/// Owned storage for the MoE weight matrices and the packed routed-expert bank, kept
/// alive in the test's scope so the `MoeW` that borrows it is valid through the
/// `decoder_layer` call. This is what C holds on the stack: the packed `float *` plus the
/// flat weight arrays, all owned by `t_layer`'s frame. test_ops.c:693-704.
struct LayerMoeWeights {
    gate: Vec<f32>,
    bias: Vec<f32>,
    down: Vec<f32>,
    up: Vec<f32>,
    norm: Vec<f32>,
    sh1: Vec<f32>,
    sh3: Vec<f32>,
    sh2: Vec<f32>,
    w1: Vec<f32>,
    w3: Vec<f32>,
    w2: Vec<f32>,
}

impl LayerMoeWeights {
    /// Load and pack all the MoE weights for a layer fixture. The routed expert bank is
    /// packed contiguously exactly as C's inline loop does: `w1[expert * inter * latent]`,
    /// `w3` the same, `w2[expert * latent * inter]`.
    fn load(r: &serde_json::Value, c: &Cfg) -> LayerMoeWeights {
        let per13 = (c.moe_inter * c.latent) as usize;
        let per2 = (c.latent * c.moe_inter) as usize;
        LayerMoeWeights {
            gate: arr(r, "mlp_gate_weight"),
            bias: arr(r, "mlp_e_score_correction_bias"),
            down: arr(r, "mlp_down_weight"),
            up: arr(r, "mlp_up_weight"),
            norm: arr(r, "mlp_norm_weight"),
            sh1: arr(r, "mlp_shared_w1_weight"),
            sh3: arr(r, "mlp_shared_w3_weight"),
            sh2: arr(r, "mlp_shared_w2_weight"),
            w1: pack_experts(r, "mlp_experts_{}_w1_weight", c.n_experts as usize, per13),
            w3: pack_experts(r, "mlp_experts_{}_w3_weight", c.n_experts as usize, per13),
            w2: pack_experts(r, "mlp_experts_{}_w2_weight", c.n_experts as usize, per2),
        }
    }

    /// Build the borrow-checked view. Resident fixtures: no expert source.
    fn view(&self) -> MoeW<'_> {
        MoeW {
            gate: &self.gate,
            bias: Some(&self.bias),
            w1: Some(&self.w1),
            w3: Some(&self.w3),
            w2: Some(&self.w2),
            latent_norm: Some(&self.norm),
            down: WMat::F32(&self.down),
            up: WMat::F32(&self.up),
            sh1: WMat::F32(&self.sh1),
            sh3: WMat::F32(&self.sh3),
            sh2: WMat::F32(&self.sh2),
            layer: 0,
            cache_only: false,
        }
    }
}

/// Owned storage for one attention flavour's weights. Exactly one of the MLA block or
/// the KDA block is populated, matching the `is_mla` field in the fixture. The shared
/// norm/proj weights (`in_norm`, `post_norm`, `attn_res_*`, `mlp_res_*`) live in
/// `layer_case` directly, since they are present for both flavours. test_ops.c:665-691.
struct LayerAttnWeights {
    // MLA
    q_a: Vec<f32>,
    q_a_norm: Vec<f32>,
    q_b: Vec<f32>,
    kv_a: Vec<f32>,
    kv_a_norm: Vec<f32>,
    kv_b: Vec<f32>,
    o: Vec<f32>,
    g: Vec<f32>,
    // KDA
    q: Vec<f32>,
    k: Vec<f32>,
    v: Vec<f32>,
    q_conv: Vec<f32>,
    k_conv: Vec<f32>,
    v_conv: Vec<f32>,
    f_a: Vec<f32>,
    f_b: Vec<f32>,
    a_log: Vec<f32>,
    dt_bias: Vec<f32>,
    b: Vec<f32>,
    o_norm: Vec<f32>,
}

impl LayerAttnWeights {
    fn load(r: &serde_json::Value, is_mla: bool) -> LayerAttnWeights {
        if is_mla {
            LayerAttnWeights {
                q_a: arr(r, "self_attn_q_a_proj_weight"),
                q_a_norm: arr(r, "self_attn_q_a_layernorm_weight"),
                q_b: arr(r, "self_attn_q_b_proj_weight"),
                kv_a: arr(r, "self_attn_kv_a_proj_with_mqa_weight"),
                kv_a_norm: arr(r, "self_attn_kv_a_layernorm_weight"),
                kv_b: arr(r, "self_attn_kv_b_proj_weight"),
                o: arr(r, "self_attn_o_proj_weight"),
                g: arr(r, "self_attn_g_proj_weight"),
                q: Vec::new(),
                k: Vec::new(),
                v: Vec::new(),
                q_conv: Vec::new(),
                k_conv: Vec::new(),
                v_conv: Vec::new(),
                f_a: Vec::new(),
                f_b: Vec::new(),
                a_log: Vec::new(),
                dt_bias: Vec::new(),
                b: Vec::new(),
                o_norm: Vec::new(),
            }
        } else {
            LayerAttnWeights {
                q_a: Vec::new(),
                q_a_norm: Vec::new(),
                q_b: Vec::new(),
                kv_a: Vec::new(),
                kv_a_norm: Vec::new(),
                kv_b: Vec::new(),
                // KDA's full-rank gate, shared field name with MLA's output gate.
                g: arr(r, "self_attn_g_proj_weight"),
                q: arr(r, "self_attn_q_proj_weight"),
                k: arr(r, "self_attn_k_proj_weight"),
                v: arr(r, "self_attn_v_proj_weight"),
                q_conv: arr(r, "self_attn_q_conv1d_weight"),
                k_conv: arr(r, "self_attn_k_conv1d_weight"),
                v_conv: arr(r, "self_attn_v_conv1d_weight"),
                f_a: arr(r, "self_attn_f_a_proj_weight"),
                f_b: arr(r, "self_attn_f_b_proj_weight"),
                a_log: arr(r, "self_attn_A_log"),
                dt_bias: arr(r, "self_attn_dt_bias"),
                b: arr(r, "self_attn_b_proj_weight"),
                o_norm: arr(r, "self_attn_o_norm_weight"),
                o: arr(r, "self_attn_o_proj_weight"),
            }
        }
    }

    fn view(&self, is_mla: bool) -> Attn<'_> {
        if is_mla {
            Attn::Mla(MlaW {
                q_a: WMat::F32(&self.q_a),
                q_b: WMat::F32(&self.q_b),
                kv_a: WMat::F32(&self.kv_a),
                kv_b: WMat::F32(&self.kv_b),
                o: WMat::F32(&self.o),
                g: Some(WMat::F32(&self.g)),
                q_a_norm: &self.q_a_norm,
                kv_a_norm: &self.kv_a_norm,
            })
        } else {
            Attn::Kda(KdaW {
                q: WMat::F32(&self.q),
                k: WMat::F32(&self.k),
                v: WMat::F32(&self.v),
                q_conv: &self.q_conv,
                k_conv: &self.k_conv,
                v_conv: &self.v_conv,
                f_a: WMat::F32(&self.f_a),
                f_b: WMat::F32(&self.f_b),
                a_log: &self.a_log,
                dt_bias: &self.dt_bias,
                b: WMat::F32(&self.b),
                g: WMat::F32(&self.g),
                o_norm: &self.o_norm,
                o: WMat::F32(&self.o),
            })
        }
    }
}

fn layer_case(file: &str) {
    // t_layer. test_ops.c:627. A whole decoder layer: AttnRes wiring plus attention plus
    // MoE. The C test hardcodes the model-level config (n_layers=13, etc.) and reads only
    // the per-layer dims from the fixture.
    let f = Fixtures::ops();
    let r = f.load(file);
    let li = num_i32(&r, "layer_idx", 0);
    let is_mla = boolean(&r, "is_mla", 0) != 0;

    let mut c = cfg_zero();
    c.hidden = num_i32(&r, "hidden", 0);
    c.rms_eps = num_f32(&r, "rms_eps", 1e-5);
    c.attn_res_block = num_i32(&r, "attn_res_block_size", 3);
    c.n_layers = 13;
    c.kda_heads = 4;
    c.kda_head_dim = 16;
    c.conv_k = 4;
    c.gate_lb = -5.0;
    c.n_heads = 4;
    c.q_lora = 64;
    c.kv_lora = 32;
    c.qk_nope = 24;
    c.qk_rope = 8;
    c.v_head = 16;
    c.mla_out_gate = 1;
    c.n_experts = 8;
    c.topk = 2;
    c.n_shared = 2;
    c.latent = 64;
    c.moe_inter = 48;
    c.routed_scale = 1.0;
    c.moe_renorm = 1;
    c.latent_norm = 1;
    c.situ_b1 = 4.0;
    c.situ_b2 = 25.0;
    c.first_dense = 1;
    c.dense_inter = 96;
    c.full_attn = vec![4, 8, 12, 13];

    let x = arr(&r, "in");
    let eo = arr(&r, "out");
    let bri = arr(&r, "block_residual_in");

    let in_norm = arr(&r, "input_layernorm_weight");
    let post_norm = arr(&r, "post_attention_layernorm_weight");
    let attn_res_norm = arr(&r, "self_attention_res_norm_weight");
    let attn_res_proj = arr(&r, "self_attention_res_proj_weight");
    let mlp_res_norm = arr(&r, "mlp_res_norm_weight");
    let mlp_res_proj = arr(&r, "mlp_res_proj_weight");

    // All weight storage is owned by this frame and the views borrow from it, exactly as
    // the C test holds the packed `float *` on its stack.
    let moe_w = LayerMoeWeights::load(&r, &c);
    let attn_w = LayerAttnWeights::load(&r, is_mla);
    let moe = moe_w.view();
    let attn = attn_w.view(is_mla);

    let lw = LayerW {
        in_norm: &in_norm,
        post_norm: &post_norm,
        attn_res_norm: &attn_res_norm,
        attn_res_proj: &attn_res_proj,
        mlp_res_norm: &mlp_res_norm,
        mlp_res_proj: &mlp_res_proj,
        attn,
        moe: Some(moe),
        dense_gate: None,
        dense_up: None,
        dense_down: None,
    };

    let din = shape(&r, "in");
    let t = din[1] as usize;
    let dbr = shape(&r, "block_residual_in");
    let nb_in = dbr[1] as usize;
    let maxb = (c.n_layers / c.attn_res_block + 2) as usize;
    let e = c.hidden as usize;

    let mut h = vec![0.0f32; t * e];
    let mut br = vec![0.0f32; t * maxb * e];
    let mut sc = vec![0.0f32; k3::ops::layer_scratch(&c, t)];
    let p = (c.kda_heads * c.kda_head_dim) as usize;
    let mut st = vec![0.0f32; p * c.kda_head_dim as usize + 3 * p * (c.conv_k - 1) as usize];
    let mut nb = nb_in;

    h.copy_from_slice(&x);
    for ti in 0..t {
        for b in 0..nb_in {
            br[(ti * maxb + b) * e..(ti * maxb + b + 1) * e]
                .copy_from_slice(&bri[(ti * nb_in + b) * e..(ti * nb_in + b + 1) * e]);
        }
    }
    decoder_layer(
        &mut h,
        &mut br,
        &mut nb,
        &lw,
        &c,
        li,
        t,
        Some(&mut st),
        &mut sc,
        None,
    );
    assert_close(file, &h, &eo, f.atol, f.rtol);
}

