// ---------------------------------------------------------------------- mxfp4 ----

#[test]
fn mxfp4_case() {
    // t_mxfp4. test_ops.c:743. Dequant, checked against REAL Kimi K3 checkpoint bytes.
    // Exact equality: dequant is a table lookup times a power of two, so there is no
    // rounding anywhere and anything but a bit-exact match is a bug. The negative case
    // (asserting the swapped-nibble result is NOT produced) is the nibble-order guard.
    let f = Fixtures::ops();
    let r = match f.load_mxfp4() {
        Some(v) => v,
        None => {
            // A skip is a failure, exactly as the C harness counts it. test_ops.c:752-755.
            panic!("mxfp4: fixture absent (run tools/fetch_mxfp4.py); a skip is not a pass");
        }
    };
    let rows = num_i32(&r, "rows", 0) as usize;
    let pcols = num_i32(&r, "packed_cols", 0) as usize;
    let grp = num_i32(&r, "group_size", 32) as usize;
    let ef = arr(&r, "expected");
    assert!(rows > 0 && pcols > 0, "mxfp4: rows/packed_cols missing");
    let p = arr_u8(&r, "packed");
    let s = arr_u8(&r, "scales");
    let width = pcols * 2;
    let mut y = vec![0.0f32; rows * width];
    mxfp4_dequant(&mut y, &p, &s, rows, pcols, grp);
    assert_eq!(y.len(), ef.len(), "mxfp4: output length mismatch");
    let mut bad = 0usize;
    let mut worst = 0.0f64;
    let mut at = 0usize;
    for i in 0..y.len() {
        let d = ((y[i] as f64) - (ef[i] as f64)).abs();
        if d > worst {
            worst = d;
            at = i;
        }
        if d != 0.0 {
            bad += 1;
        }
    }
    assert_eq!(
        bad,
        0,
        "mxfp4: {bad} of {} elements differ, worst {worst:.7} at {at} (got {:.7} want {:.7})",
        y.len(),
        y[at],
        ef[at]
    );

    // NIBBLE ORDER IS A CONVENTION, NOT A RULE: the low nibble of each byte is the EVEN
    // element. Reversing it yields a matrix with exactly the right values in the wrong
    // places, so every statistic looks perfect and the model is wrong. Assert the
    // swapped-nibble result is NOT produced: dequant with the nibbles swapped must
    // disagree with the expected output somewhere. This is the guard the C test's
    // comment block describes; the explicit check lives here because it is the only
    // place that has the real bytes. k3_ops.c:1331, dispatch.rs mxfp4_dequant.
    let mut y_swap = vec![0.0f32; rows * width];
    mxfp4_dequant_swap(&mut y_swap, &p, &s, rows, pcols, grp);
    let mut swap_disagrees = false;
    for i in 0..y_swap.len() {
        if y_swap[i] as f64 != ef[i] as f64 {
            swap_disagrees = true;
            break;
        }
    }
    assert!(
        swap_disagrees,
        "mxfp4: swapped-nibble dequant matched the expected output, which means the \
         nibble order is NOT actually being enforced (low nibble must be the EVEN element)"
    );
}

/// A dequant that swaps the nibble convention (high nibble first), used only to prove the
/// real `mxfp4_dequant` does NOT produce this result. Mirrors `mxfp4_dequant` line for line
/// except for the nibble extraction.
fn mxfp4_dequant_swap(
    out: &mut [f32],
    packed: &[u8],
    scales: &[u8],
    rows: usize,
    pcols: usize,
    group: usize,
) {
    let width = pcols * 2;
    let ngrp = width.div_ceil(group);
    let e2m1 = k3::ops::dispatch::E2M1;
    let e8m0 = k3::ops::dispatch::E8M0;
    for r in 0..rows {
        let pr = &packed[r * pcols..(r + 1) * pcols];
        let sr = &scales[r * ngrp..(r + 1) * ngrp];
        let orow = &mut out[r * width..(r + 1) * width];
        for g in 0..ngrp {
            let mult = e8m0[sr[g] as usize];
            let lo = g * group;
            let hi = core::cmp::min(lo + group, width);
            for i in lo..hi {
                let byte = pr[i >> 1];
                // SWAPPED: high nibble is the EVEN element here.
                let nib = if i & 1 != 0 { byte & 0x0F } else { byte >> 4 };
                orow[i] = e2m1[nib as usize] * mult;
            }
        }
    }
}

// ------------------------------------------------------------------ matmul_bf16 ----

#[test]
fn matmul_bf16_case() {
    // t_matmul_bf16. test_ops.c:811. k3_matmul_bf16 must equal k3_matmul EXACTLY, not
    // approximately. Both widen the same bf16 values to the same f32 values (a left shift
    // by 16, which is lossless), then accumulate in double in the same order with the same
    // sixteen partial sums. So the only way they can differ is if one of them is wrong.
    //
    // This test needs no fixture. It generates bf16 bit patterns directly, which also means
    // it covers values a Gaussian sample would never produce - the checkpoint contains
    // denormals and very large exponents, and the widen must handle them by construction
    // rather than by luck.
    let inp = 257usize; // deliberately not a multiple of 4
    let out = 129usize;
    let mut wb = vec![0u16; inp * out];
    let mut wf = vec![0.0f32; inp * out];
    let mut x = vec![0.0f32; inp];
    let mut ya = vec![0.0f32; out];
    let mut yb = vec![0.0f32; out];

    let mut s: u32 = 0xC0FFEE;
    for i in 0..inp * out {
        s ^= s << 13;
        s ^= s >> 17;
        s ^= s << 5;
        // Any 16-bit pattern EXCEPT the NaN/Inf exponent, which would make every
        // comparison trivially NaN and prove nothing.
        let mut h = (s >> 8) as u16;
        if ((h >> 7) & 0xFF) == 0xFF {
            h &= 0x7F7F;
        }
        wb[i] = h;
        wf[i] = bf16f(h); // the SAME value, stored wide
    }
    for i in 0..inp {
        s ^= s << 13;
        s ^= s >> 17;
        s ^= s << 5;
        x[i] = (s >> 8) as f32 / 8388608.0 - 1.0;
    }

    matmul(&mut ya, &x, &wf, inp);
    matmul_bf16(&mut yb, &x, &wb, inp);

    let mut bad = 0usize;
    for o in 0..out {
        if ya[o].to_bits() != yb[o].to_bits() {
            bad += 1;
        }
    }
    assert_eq!(
        bad, 0,
        "matmul_bf16: {bad}/{out} rows differ from the fp32 path"
    );
}

// ----------------------------------------------------------- dispatched vs plain ----

/// A deterministic xorshift32, matching the C test's `s ^= s << 13; s ^= s >> 17; s << 5`
/// generator. No `rand`: the test must produce the same sequence on every run and every
/// platform, and the C gate does the same.
fn lcg_next(s: &mut u32) -> u32 {
    *s ^= *s << 13;
    *s ^= *s >> 17;
    *s ^= *s << 5;
    *s
}

/// The 16-lane f64 partition and reduction tree from `dispatch::dot_f32`, reproduced here
/// in the test so the dispatched kernel can be checked against it bit for bit. This is the
/// Rust replacement for the C build's scalar-vs-AVX2 gate: `dispatch.rs` exposes
/// `pub(crate) fn plain()` and `pub(crate) fn kernels()`, which an integration test cannot
/// reach, so the only way an external test can assert the selected kernels agree with the
/// un-multiversioned bodies is to rebuild the same reduction here and compare `to_bits`.
fn ref_dot_f32(row: &[f32], x: &[f32]) -> f64 {
    let n = row.len();
    let mut a = [0.0f64; 16];
    let mut i = 0usize;
    while i + 15 < n {
        for l in 0..16 {
            a[l] = (row[i + l] as f64).mul_add(x[i + l] as f64, a[l]);
        }
        i += 16;
    }
    let b0 = (a[0] + a[4]) + (a[8] + a[12]);
    let b1 = (a[1] + a[5]) + (a[9] + a[13]);
    let b2 = (a[2] + a[6]) + (a[10] + a[14]);
    let b3 = (a[3] + a[7]) + (a[11] + a[15]);
    let mut acc = (b0 + b1) + (b2 + b3);
    while i < n {
        acc = (row[i] as f64).mul_add(x[i] as f64, acc);
        i += 1;
    }
    acc
}

/// The 16-lane f64 partition and reduction tree from `dispatch::dot_bf16`, reproduced here
/// for the same reason. bf16 -> f32 is a pure 16-bit left shift.
fn ref_dot_bf16(row: &[u16], x: &[f32]) -> f64 {
    let n = row.len();
    let mut a = [0.0f64; 16];
    let mut i = 0usize;
    while i + 15 < n {
        for l in 0..16 {
            a[l] = (bf16f(row[i + l]) as f64).mul_add(x[i + l] as f64, a[l]);
        }
        i += 16;
    }
    let b0 = (a[0] + a[4]) + (a[8] + a[12]);
    let b1 = (a[1] + a[5]) + (a[9] + a[13]);
    let b2 = (a[2] + a[6]) + (a[10] + a[14]);
    let b3 = (a[3] + a[7]) + (a[11] + a[15]);
    let mut acc = (b0 + b1) + (b2 + b3);
    while i < n {
        acc = (bf16f(row[i]) as f64).mul_add(x[i] as f64, acc);
        i += 1;
    }
    acc
}

/// The 8-lane f64 partition and per-group reduction tree from `dispatch::dot_mxfp4`,
/// reproduced here. Each group of 32 is expanded to `wf[64]` via the E2M1 pair table, dotted
/// with eight f64 lanes, reduced `(s0+s4)+(s1+s5)...`, and the group's E8M0 scale is applied
/// as a separate multiply-then-add.
fn ref_dot_mxfp4(packed: &[u8], scales: &[u8], x: &[f32], input: usize, group: usize) -> f64 {
    let ngrp = input.div_ceil(group);
    let gbyte = group / 2;
    let mut acc = 0.0f64;
    for g in 0..ngrp {
        let sb = scales[g];
        if sb == 255 {
            continue;
        }
        let pb = &packed[g * gbyte..];
        let xg = &x[g * group..];
        let n = core::cmp::min(input - g * group, group);
        let mut wf = [0.0f32; 64];
        let half = n >> 1;
        for j in 0..half {
            let pv = &k3::ops::dispatch::E2M1_PAIR[pb[j] as usize];
            wf[2 * j] = pv[0];
            wf[2 * j + 1] = pv[1];
        }
        if n & 1 != 0 {
            wf[n - 1] = k3::ops::dispatch::E2M1_PAIR[pb[half] as usize][0];
        }
        let mut s = [0.0f64; 8];
        let mut i = 0usize;
        while i + 7 < n {
            for l in 0..8 {
                s[l] = (wf[i + l] as f64).mul_add(xg[i + l] as f64, s[l]);
            }
            i += 8;
        }
        let b0 = s[0] + s[4];
        let b1 = s[1] + s[5];
        let b2 = s[2] + s[6];
        let b3 = s[3] + s[7];
        let mut sub = (b0 + b1) + (b2 + b3);
        while i < n {
            sub = (wf[i] as f64).mul_add(xg[i] as f64, sub);
            i += 1;
        }
        acc += sub * k3::ops::dispatch::E8M0[sb as usize] as f64;
    }
    acc
}

/// Build a deterministic f32 in [-1, 1) from the LCG, matching the C scale_test.c fill()
/// shape (which uses the same xorshift and the same `/ 8388608.0 - 1.0` mapping).
fn lcg_f32(s: &mut u32) -> f32 {
    (lcg_next(s) >> 8) as f32 / 8388608.0 - 1.0
}

#[test]
fn dispatched_matches_plain_reference() {
    // This is the Rust replacement for the C build's scalar-vs-AVX2 gate.
    //
    // `dispatch.rs` multiversions the row kernels on x86-64: it stamps each body out once
    // plain and once under `#[target_feature(enable = "avx2,fma")]`, then selects between
    // them at startup via a `OnceLock` of function pointers. An integration test cannot
    // reach the `pub(crate) fn plain()` / `pub(crate) fn kernels()` selectors, so the only
    // way to assert the selected kernels agree with the un-multiversioned bodies is to
    // rebuild the same lane partitions and reduction trees here and compare `f32::to_bits`
    // on deterministic pseudo-random data. If the dispatched path ever diverged from this
    // reference, it would mean the AVX2 clone introduced a reassociation or a different
    // widen - which is the exact bug the C gate exists to catch.
    //
    // On aarch64 FMA and NEON are baseline, so the plain body already compiles to `fmla`
    // and there is nothing to select; the test still passes because the reference is the
    // same arithmetic the plain body uses.
    let mut s: u32 = 0xDEADBEEF;

    // ---- matmul (f32) ----
    let inp = 257usize;
    let out = 66usize; // exercises the `> 64` parallel path
    let mut w = vec![0.0f32; out * inp];
    let mut x = vec![0.0f32; inp];
    for v in &mut w {
        *v = lcg_f32(&mut s);
    }
    for v in &mut x {
        *v = lcg_f32(&mut s);
    }
    let mut y = vec![0.0f32; out];
    matmul(&mut y, &x, &w, inp);
    let mut bad = 0usize;
    for o in 0..out {
        let want = ref_dot_f32(&w[o * inp..o * inp + inp], &x) as f32;
        if y[o].to_bits() != want.to_bits() {
            bad += 1;
        }
    }
    assert_eq!(
        bad, 0,
        "matmul: {bad}/{out} rows differ from the reference dot"
    );

    // ---- matmul_bf16 ----
    let mut wb = vec![0u16; out * inp];
    let mut wf = vec![0.0f32; out * inp];
    for i in 0..out * inp {
        let mut h = (lcg_next(&mut s) >> 8) as u16;
        if ((h >> 7) & 0xFF) == 0xFF {
            h &= 0x7F7F;
        }
        wb[i] = h;
        wf[i] = bf16f(h);
    }
    let mut x2 = vec![0.0f32; inp];
    for v in &mut x2 {
        *v = lcg_f32(&mut s);
    }
    let mut yb = vec![0.0f32; out];
    let mut yf = vec![0.0f32; out];
    matmul_bf16(&mut yb, &x2, &wb, inp);
    matmul(&mut yf, &x2, &wf, inp);
    let mut bad = 0usize;
    for o in 0..out {
        // bf16 path must be bit-identical to the f32 path (same widen, same tree) AND to
        // the reference dot.
        if yb[o].to_bits() != yf[o].to_bits() {
            bad += 1;
        }
        let want = ref_dot_bf16(&wb[o * inp..o * inp + inp], &x2) as f32;
        if yb[o].to_bits() != want.to_bits() {
            bad += 1;
        }
    }
    assert_eq!(
        bad, 0,
        "matmul_bf16: {bad}/{out} rows differ from the f32 path or reference"
    );

    // ---- matmul_mxfp4 ----
    // A small but non-trivial MXFP4 matrix: input=64 (one full group of 32 plus a partial
    // group), rows=70 (> 64, parallel path). Packed cols = input/2 = 32 bytes/row. One
    // E8M0 scale per 32 elements = 2 scales/row. The group size is the model's 32.
    let inp_m = 64usize;
    let rows_m = 70usize;
    let group = 32usize;
    let pcols = inp_m / 2;
    let ngrp = inp_m.div_ceil(group);
    let mut packed = vec![0u8; rows_m * pcols];
    let mut scales = vec![0u8; rows_m * ngrp];
    for v in &mut packed {
        *v = (lcg_next(&mut s) >> 8) as u8;
    }
    for v in &mut scales {
        // Avoid 255 (NaN) and 0 (tiny) so every group contributes a normal scale.
        *v = ((lcg_next(&mut s) >> 8) % 254 + 1) as u8;
    }
    let mut xm = vec![0.0f32; inp_m];
    for v in &mut xm {
        *v = lcg_f32(&mut s);
    }
    let mut ym = vec![0.0f32; rows_m];
    matmul_mxfp4(&mut ym, &xm, &packed, &scales, inp_m, group);
    let mut bad = 0usize;
    for r in 0..rows_m {
        let want = ref_dot_mxfp4(
            &packed[r * pcols..(r + 1) * pcols],
            &scales[r * ngrp..(r + 1) * ngrp],
            &xm,
            inp_m,
            group,
        ) as f32;
        if ym[r].to_bits() != want.to_bits() {
            bad += 1;
        }
    }
    assert_eq!(
        bad, 0,
        "matmul_mxfp4: {bad}/{rows_m} rows differ from the reference dot"
    );
}

// ----------------------------------------------------------------- sanity l2norm ----

#[test]
fn l2norm_case() {
    // A quick sanity that l2norm matches the reference's sum-of-squares with eps inside the
    // rsqrt (NOT the mean). This is invariant 1's neighbour: using the mean here scales
    // every q and k by sqrt(d_k) and quietly changes the attention temperature. The
    // kernel is exercised inside kda_layer above, but the standalone check pins the
    // formula directly. k3_ops.c:792.
    let mut v = [3.0f32, 4.0, 0.0, 0.0];
    l2norm(&mut v, 1e-6);
    // sum of squares = 25, so inv = 1/sqrt(25 + eps) and each element is scaled by ~0.2.
    // Dividing by sqrt(5) instead would be the mean-based form this kernel deliberately
    // is not.
    let inv = 1.0 / (25.0f32 + 1e-6).sqrt();
    let expect0 = 3.0 * inv;
    let expect1 = 4.0 * inv;
    assert!(
        (v[0] - expect0).abs() < 1e-5 && (v[1] - expect1).abs() < 1e-5,
        "l2norm: got [{}, {}, {}, {}] expected [{}, {}, 0, 0]",
        v[0],
        v[1],
        v[2],
        v[3],
        expect0,
        expect1
    );
    assert_eq!(v[2], 0.0);
    assert_eq!(v[3], 0.0);
}
